#include <bits/stdc++.h>
using namespace std;

using ll = long long;

void solve() {
    ll a;
    cin >> a;

    vector<int> answer;

    while (a > 0) {
        if (a % 10 < 8) {
            answer.push_back(8);
            while (a > 0) {
                answer.push_back(a % 10);
                a /= 10;
            }
            break;
        } else {
            answer.push_back(0);
            a /= 10;
        }
    }

    for (int i = static_cast<int>(answer.size()) - 1; i >= 0; --i) {
        cout << answer[i];
    }
    cout << '\n';
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    solve();
    return 0;
}

